/**
 * Case-insensitive search, ranked so the obvious answer wins.
 *
 * Without ranking, dataset order decides — searching "fire" would surface
 * the compound heart-on-fire before the actual fire emoji, because it happens
 * to sort earlier. Lower score sorts first.
 */
function score(entry: EmojiEntry, q: string): number {
  if (entry.n === q) return 0 // exact name: "fire" -> fire
  // A word of the name beats a tag match, so "heart" finds red heart before
  // kiss (which merely carries "heart" as a tag).
  if (entry.n.split(' ').includes(q)) return 1
  if (entry.n.startsWith(q)) return 2 // "fire truck"
  if (entry.k.includes(q)) return 3 // exact tag
  if (entry.k.some((k) => k.startsWith(q))) return 4
  if (entry.n.includes(q)) return 5
  return Infinity
}

export function searchEmojis(query: string, limit = 240): EmojiEntry[] {
  const q = query.trim().toLowerCase()
  if (!q) return EMOJIS.slice(0, limit)

  const hits: { entry: EmojiEntry; rank: number; order: number }[] = []

  EMOJIS.forEach((entry, order) => {
    const rank = score(entry, q)
    if (rank !== Infinity) hits.push({ entry, rank, order })
  })

  // Shorter names first within a rank, so "fire" beats "fire engine".
  hits.sort(
    (a, b) =>
      a.rank - b.rank || a.entry.n.length - b.entry.n.length || a.order - b.order,
  )

  return hits.slice(0, limit).map((h) => h.entry)
}
